// === Tab: mySketch.js ===
// Please turn on Hardware Acceleration in browser if not already.
// This sketch is labeled as forked, but the original sketch used the p5wgex.js library 
// which with I was not able to combine the 2D fish sketch. So this sketch
// lacks the Camara usage and is only mouse linked. I used the original
// shadertoy sketch https://www.shadertoy.com/view/7dyXWC by rockhard
// The fish sketch is based on an older Java sketch by Tara Schwenzfeier

let oceanShader;
let fishBuffer; 
let startTime;
let numLayers = 200; 
let layers = [];
let bodySize = 150; 
let movementSpeed = 1; 
let prevX = 0, prevY = 0; 
let mouseXSmoothed = 0,	mouseYSmoothed = 0, smoothedMouseY = 0; 
let radiusSmoothed = 0, offsetYSmoothed = 0, offsetXSmoothed = 0,	tailRadiusSmoothed = 0,	layerFactorSmoothed = 0;
let rotationA, rotationB, eyeDrawn;
let buffer; 
let img;

function preload() {
  img = loadImage('https://openprocessing.org/sketch/2452217/files/starfish.gif');
}

function setup() {
	createCanvas(1920, 1080, WEBGL);
	buffer = createGraphics(1920, 1080);
  noCursor();
	for (let i = numLayers - 1; i >= 0; i--) layers[i] = new Layer(i);
	pixelDensity(1);
	oceanShader = createShader(vsOcean, fsOcean);
	fishBuffer = createGraphics(windowWidth, windowHeight);
	startTime = millis();
}

function draw() {
  const elapsedTime = (millis() - startTime) / 1000.0;
  const easingFactor = 0.08;  
  let normalizedMouseY = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1.0, 0.0);
  smoothedMouseY = lerp(smoothedMouseY, normalizedMouseY, easingFactor);
  let normalizedMouseX = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.0, 1.0);
  oceanShader.setUniform('uMouseY', smoothedMouseY);
	oceanShader.setUniform('uMouseX', normalizedMouseX);
  oceanShader.setUniform('uResolution', [width, height]);
  oceanShader.setUniform('uTime', elapsedTime);
  shader(oceanShader);
  beginShape();
  vertex(-1, -1, 0, 0); // Bottom-left
  vertex(1, -1, 1, 0);  // Bottom-right
  vertex(1, 1, 1, 1);   // Top-right
  vertex(-1, 1, 0, 1);  // Top-left
  endShape(CLOSE);
	buffer.clear();
	mouseXSmoothed = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	mouseYSmoothed = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	eyeDrawn = 0; 
	for (let i = numLayers - 1; i >= 0; i--) layers[i].updateLayer();
	for (let i = 0; i < numLayers; i++) layers[i].drawLayer(buffer); 
	resetMatrix(); // Reset any WebGL transformations
	ortho(); // Switch to 2D orthographic projection
  translate(-width/2, -height/2);
	image(buffer, 0, 0);
	image(img, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

// Vertex Shader (WebGL1-compatible)
const vsOcean = `
  attribute vec2 aPosition;
  varying vec2 vUv;

  void main() {
    vUv = aPosition * 0.5 + 0.5;
    gl_Position = vec4(aPosition, 0.0, 1.0);
  }
`;

// Fragment Shader (WebGL2-compatible, corrected)
const fsOcean = `
precision highp float;
uniform vec2 uResolution;
uniform float uTime;
uniform float uMouseY;
uniform float uMouseX;  
uniform float uAspect;

#define STEP 36
#define FAR 35.0

varying vec2 vUv;

float wavedx(vec2 position, vec2 direction, float time, float freq){
  float x = dot(direction, position) * freq + time;
  return exp(sin(x) - 1.0);
}

float getwaves(vec2 position){
  float iter = 0.0, phase = 6.0, speed = 2.0;
  float weight = 1.0, w = 0.0, ws = 0.0;   
  for(int i = 0; i < 5; i++){
    vec2 p = vec2(sin(iter), cos(iter));
    float res = wavedx(position, p, speed * uTime, phase);        
    w += res * weight; 
    ws += weight;
    iter += 12.0; 
    weight *= 0.75; 
    phase *= 1.18; 
    speed *= 1.08;
  }
  return w / ws;
}

float sea_octave(vec2 uv, float choppy) {
  return getwaves(uv * choppy) + getwaves(uv);
}

float noise3D(vec3 p) { 
  vec3 s = vec3(7.0, 157.0, 113.0);
  vec3 ip = floor(p); 
  vec4 h = vec4(0.0, s.yz, s.y + s.z) + dot(ip, s);
  p -= ip; 
  p = p * p * (3.0 - 2.0 * p); 
  h = mix(fract(sin(h) * 43758.5453), fract(sin(h + s.x) * 43758.5453), p.x); 
  h.xy = mix(h.xz, h.yw, p.y); 
  return mix(h.x, h.y, p.z);  
}

float smaxP(float a, float b, float s){
  float h = clamp(0.5 + 0.5 * (a - b) / s, 0.0, 1.0);
  return mix(b, a, h) + h * (1.0 - h) * s;
}

vec3 Freq = vec3(0.125, 0.31, 0.128), Amp = vec3(1.0, 1.5, 2.5);

vec2 path(float z) {
  return vec2(Amp.x * sin(z * Freq.x), Amp.y * cos(z * Freq.y) + Amp.z * (sin(z * Freq.z) - 1.0));
}

float map(vec3 p) {
  float n = noise3D(p);
  float tx = n;
  vec3 q = p * 0.35;  
  float h = dot(sin(q) * cos(q.yzx), vec3(0.222)) + dot(sin(q * 1.5) * cos(q.yzx * 1.5), vec3(0.111));    
  float d = p.y + h * 3.9;
  q = sin(p * 0.5 + h);
  h = q.x * q.y * q.z;
  p.xy -= path(p.z);
  float tnl = 1.5 - length(p.xy * vec2(0.33, 0.66)) + (0.25 - tx * 0.35);  
  return smaxP(d, tnl, 2.0) - tx * 0.25 + tnl * 0.8;
}

float logBisectTrace(vec3 ro, vec3 rd) {
  float t = 0.0, told = 0.0, mid, dn;
  float d = map(ro);
  float sgn = sign(d);
  for (int i = 0; i < STEP; i++) {
    if (sign(d) != sgn || d < 0.001 || t > FAR) break;
    told = t;
    t += step(d, 1.0) * (log(abs(d) + 1.1) - d) + d;        
    d = map(rd * t + ro);
  }

  if (sign(d) != sgn) {    
    dn = sign(map(rd * told + ro));        
    vec2 iv = vec2(told, t);
    for (int ii = 0; ii < 5; ii++) { 
      mid = dot(iv, vec2(0.5));
      d = map(rd * mid + ro);
      if (abs(d) < 0.001) break;
      iv = mix(vec2(iv.x, mid), vec2(mid, iv.y), step(0.0, d * dn));
    }
    t = mid;       
  }
  return min(t, FAR);
}

vec3 normal(vec3 p, float t) { 
  vec2 e = vec2(-t, t);   
  return normalize(e.yxx * map(p + e.yxx) + e.xxy * map(p + e.xxy) + 
                   e.xyx * map(p + e.xyx) + e.y * map(p + e.y));   
}

vec3 rotY(vec3 v, float a) {
  float c = cos(a), s = sin(a);
  return vec3(c * v.x - s * v.z, v.y, s * v.x + c * v.z);
}

void main() {
  vec2 uv = vUv * uResolution.xy / uResolution.y - 0.5;
  uv.x *= uResolution.x / uResolution.y;

  float time = uTime * 0.2;
  vec3 pos = (sin(time * 0.14) * 2.0 + 4.5) * vec3(sin(time * 0.5), 0.0, cos(time * 0.5));
  pos.z -= time;

  // Apply mouse Y influence
  pos.y += (uMouseY - 0.5) * 3.0;

  // Apply mouse X influence (opposite direction)
  pos.x -= (uMouseX - 0.5) * 1.0;

  pos.y += 0.7 * sin(time * 0.2);
  float rot = -time * 0.5;
  vec3 dir = normalize(vec3(uv, -0.6));
  dir = rotY(dir, rot);

  vec3 sun = vec3(-0.6, 0.5, -0.3); 
  float i = max(0.0, 1.2 / (length(sun - dir) + 1.0));
  vec3 col = vec3(pow(i, 1.9), pow(i, 1.0), pow(i, 0.8)) * 1.25;
  col = mix(col, vec3(0.0, 0.39, 0.62), (1.0 - dir.y) * 0.9);   

  if (dir.y > 0.0) { 
    float d = (pos.y - 3.0) / dir.y;  
    vec2 wat = (dir * d).xz - pos.xz;
    d += sin(wat.x + time);
    wat = (dir * d).xz - pos.xz;     
    wat = wat * 0.1;
    col += sea_octave(wat, 0.5) * 0.6 * max(2.0 / -d, 0.0);
  } else { 
    vec3 ro = pos;
    ro.y += 12.0;
    float t = logBisectTrace(ro, dir);
    vec3 rock = vec3(0.0);
    if (t < FAR) {   
      pos = ro + dir * t;
      t /= FAR;
      vec3 sn = normal(pos, 0.1 / (1.0 + t));
      float fre = clamp(1.0 + dot(sun, sn), 0.0, 1.0); 
      float Schlick = pow(1.0 - max(dot(dir, normalize(dir + sun)), 0.0), 5.0);
      fre *= mix(0.2, 1.0, Schlick);
      float dif = dot(sn, sun) * 0.2;    
      rock = (dif + fre * fre * 0.35) * col;
      float y = smoothstep(0.9, 1.0, (1.0 + dir.y)); 
      if (y > 0.0) rock = mix(rock, col, y * t);     
      col = mix(rock, col, t);
    }  
    float f = (-dir.y - 0.3 + sin(time * 0.05) * 0.2) * 0.3185;
    f = clamp(f, 0.0, 1.0);    
    col = mix(col, rock, f);
  }

  gl_FragColor = vec4(col, 1.0);
}
`;

class Layer {
	constructor(layerIndex) {
		this.layerFactor = 1 - layerIndex / numLayers; // Scaling factor for this layer
		this.bodyRadius = (30 * pow(this.layerFactor, 3) - 58.5 * sq(this.layerFactor) + 28 * this.layerFactor + 0.92) * bodySize / 2; // Calculate the radius of the body
		this.offsetY = (10 * pow(this.layerFactor, 3) - 10 * sq(this.layerFactor)) * bodySize; // Vertical offset for positioning
		this.backColor = color(255, 50 - 50 * this.layerFactor, 50 - 150 * this.layerFactor); // Red gradient for the back
		this.bellyColor = color(150, 30 - 180 * this.layerFactor, 50); // Light red color for the belly


		this.isHead = (layerIndex == numLayers - 1); // Mark if this is the first layer (head)

		if (this.layerFactor > 0.775) { // Tail area
			this.offsetX = (22 * sq(this.layerFactor) - 30 * this.layerFactor + 10) * bodySize; // Horizontal offset for the tail
			if (layerIndex == 0) { // If it's the last layer (tail)
				this.tailRadius = 0;
				this.bodyRadius = 0;
			} else {
				this.tailRadius = (-86.7 * sq(this.layerFactor) + 153.2 * this.layerFactor - 66) * bodySize / 2; // Tail radius
			}
		}

		// Set the smoothed variables
		this.bodyRadiusSmoothed = radiusSmoothed;
		this.offsetYSmoothed = offsetYSmoothed;
		this.offsetXSmoothed = offsetXSmoothed;
		this.tailRadiusSmoothed = tailRadiusSmoothed;
		this.layerFactorSmoothed = layerFactorSmoothed;

		// Update smoothed values for the next layer
		radiusSmoothed = this.bodyRadius;
		offsetYSmoothed = this.offsetY;
		offsetXSmoothed = this.offsetX;
		tailRadiusSmoothed = this.tailRadius;
		layerFactorSmoothed = this.layerFactor;
	}

	updateLayer() {
		// Update previous positions for smoothing
		this.prevX = prevX;
		this.prevY = prevY;

		// Move the body based on the smoothed mouse position
		prevX = this.currentX || 0;
		prevY = this.currentY || 0;

		if (this.isHead) { // If this is the head, follow the mouse
			this.currentX = (movementSpeed / numLayers * mouseXSmoothed + this.currentX || 0) / (movementSpeed / numLayers + 1);
			this.currentY = (movementSpeed / numLayers * mouseYSmoothed + this.currentY || 0) / (movementSpeed / numLayers + 1);
		} else { // For other layers, follow the previous layer
			this.currentX = this.prevX;
			this.currentY = this.prevY;
		}

		// Update smoothed mouse position for the next layer
		this.prevMouseX = mouseXSmoothed;
		this.prevMouseY = mouseYSmoothed;
		mouseXSmoothed = this.currentX;
		mouseYSmoothed = this.currentY;
	}

	drawLayer(buffer) {
		if (this.layerFactor <= 0.775) {
			// Draw the blue back part
			buffer.fill(this.backColor);
			buffer.noStroke();
			buffer.ellipse(this.currentX || 0, this.currentY - this.offsetY || 0, this.bodyRadius * 2 || 0, this.bodyRadius * 2 || 0); // Body (back)

			// Draw the white belly part
			buffer.fill(this.bellyColor);
			buffer.beginShape();
			for (let i = PI / 6; i <= 5 * PI / 6; i += PI / 15) {
				buffer.vertex(this.currentX + cos(i) * this.bodyRadius, this.currentY - this.offsetY + sin(i) * this.bodyRadius);
			}
			buffer.vertex(this.currentX, this.currentY - this.offsetY + this.bodyRadius / 3);
			buffer.endShape(CLOSE);

			// Draw the fins if in a certain range
			if (this.layerFactor > 0.3 && this.layerFactor <= 0.4) {
				buffer.push();
				buffer.rotate(PI / 4); // Rotate for fin positioning
				rotationA = this.currentX - this.bodyRadius;
				rotationB = this.currentY + this.bodyRadius * 0.6;
				buffer.ellipse(sqrt(sq(rotationA) + sq(rotationB)) * sin(PI / 4 + atan(rotationA / rotationB)),
					sqrt(sq(rotationA) + sq(rotationB)) * cos(PI / 4 + atan(rotationA / rotationB)),
					bodySize * (this.layerFactor - 0.3) * 15, bodySize * (this.layerFactor - 0.3) * 40); // Left fin

				rotationA = this.currentX + this.bodyRadius;
				buffer.ellipse(sqrt(sq(rotationA) + sq(rotationB)) * sin(PI / 4 + atan(rotationA / rotationB)),
					sqrt(sq(rotationA) + sq(rotationB)) * cos(PI / 4 + atan(rotationA / rotationB)),
					bodySize * (this.layerFactor - 0.3) * 40, bodySize * (this.layerFactor - 0.3) * 15); // Right fin
				buffer.pop();
			}

			// Draw the eyes on the head (smallest layer)
			if (this.layerFactor < 0.2) {
				buffer.stroke(150);
				buffer.strokeWeight(3);
				buffer.strokeWeight(0);
				if (eyeDrawn == 0) {
					for (let i = 1; i >= -1; i -= 2) {
						buffer.fill(0);
						buffer.stroke(0);
						buffer.ellipse(this.currentX + i * this.bodyRadius * 0.9, this.currentY - this.bodyRadius * 0.15, bodySize / 3, bodySize / 3); // Eye
						buffer.fill(250);
						buffer.stroke(250);
						buffer.ellipse(this.currentX + i * this.bodyRadius * 0.93, this.currentY - this.bodyRadius * 0.18, bodySize / 10, bodySize / 10); // Eye reflection
					}
					eyeDrawn = 1; // Ensure the eyes are only drawn once
				}
			}
		} else {
			// Tail drawing logic
			for (let i = 1; i >= -1; i -= 2) {
				buffer.beginShape();
				buffer.vertex(this.currentX + i * this.offsetX, this.currentY - this.offsetY + this.bodyRadius);
				buffer.vertex(this.prevMouseX + i * this.offsetXSmoothed, this.prevMouseY - this.offsetYSmoothed + this.bodyRadiusSmoothed);
				buffer.vertex(this.prevMouseX + i * this.offsetXSmoothed, this.prevMouseY - this.offsetYSmoothed - this.bodyRadiusSmoothed);
				buffer.vertex(this.currentX + i * this.offsetX, this.currentY - this.offsetY - this.bodyRadius);
				buffer.endShape(CLOSE);

				buffer.beginShape();
				buffer.vertex(this.currentX + i * this.offsetX, this.currentY - this.offsetY + this.bodyRadius);
				buffer.vertex(this.currentX + i * this.offsetX - this.tailRadius, this.currentY - this.offsetY);
				buffer.vertex(this.currentX + i * this.offsetX, this.currentY - this.offsetY - this.bodyRadius);
				buffer.vertex(this.currentX + i * this.offsetX + this.tailRadius, this.currentY - this.offsetY);
				buffer.endShape(CLOSE);

				buffer.beginShape();
				buffer.vertex(this.currentX + i * this.offsetX - this.tailRadius, this.currentY - this.offsetY);
				buffer.vertex(this.prevMouseX + i * this.offsetXSmoothed - this.tailRadiusSmoothed, this.prevMouseY - this.offsetYSmoothed);
				buffer.vertex(this.prevMouseX + i * this.offsetXSmoothed + this.tailRadiusSmoothed, this.prevMouseY - this.offsetYSmoothed);
				buffer.vertex(this.currentX + i * this.offsetX + this.tailRadius, this.currentY - this.offsetY);
				buffer.endShape(CLOSE);
			}
		}
	}
}

